-- Spec 003 Assigning courses and deadlines (specs/003-assign-deadlines/data-model.md › Migration).
-- Generated by `prisma migrate diff` (the index), then completed by hand (the policy and the partial
-- unique index, which Prisma can't express).

-- CreateIndex: Plan ranges and Today look deadlines up by student and time.
CREATE INDEX "lesson_deadlines_student_due" ON "lesson_deadlines"("student_id", "due_at");

-- Replace 0_init's deadlines_write (research.md R12). It only checked is_admin_of(student_id); the
-- server guard requireLessonDeadlineTarget also requires a Published, non-deleted lesson in a course
-- the caller owns, with an active assignment for that student. Both layers apply the same rule
-- (constitution I). Deliberate and hand-written, not a Prisma drop.
drop policy deadlines_write on public.lesson_deadlines;
create policy deadlines_write on public.lesson_deadlines for all
  using (
    is_admin_of(student_id)
    and exists (select 1 from lessons l
                join course_assignments a on a.course_id = l.course_id
                where l.id = lesson_deadlines.lesson_id and owns_course(l.course_id)
                  and l.status = 'published' and l.deleted_at is null
                  and a.student_id = lesson_deadlines.student_id and a.status = 'active'))
  with check (
    is_admin_of(student_id)
    and set_by = auth.uid()
    and exists (select 1 from lessons l
                join course_assignments a on a.course_id = l.course_id
                where l.id = lesson_deadlines.lesson_id and owns_course(l.course_id)
                  and l.status = 'published' and l.deleted_at is null
                  and a.student_id = lesson_deadlines.student_id and a.status = 'active'));

-- "Add default reminders" creates the 006 FR-008 set at most once per (admin, student) (spec 003
-- FR-013, research.md R9). Inserts use ON CONFLICT DO NOTHING (Prisma createMany skipDuplicates).
create unique index notification_rules_default_once
  on public.notification_rules (admin_id, student_id, trigger)
  where config->>'preset' = 'default';
